import { z } from "zod";

export const ConfidenceBand = z.enum(["low", "medium", "high"]);
export type ConfidenceBand = z.infer<typeof ConfidenceBand>;

/**
 * App-computed confidence (plan §12). The model NEVER produces this number.
 * `reasons` are human-readable and generated by app code.
 */
export const Confidence = z.object({
  value: z.number().min(0.05).max(0.95),
  band: ConfidenceBand,
  reasons: z.array(z.string()).max(3),
});
export type Confidence = z.infer<typeof Confidence>;

/** The three measurable signals that feed confidence. */
export const ConfidenceSignals = z.object({
  /** self-consistency: vote share of the top choice across k samples */
  S: z.number().min(0).max(1),
  /** evidence strength */
  E: z.number().min(0).max(1),
  /** Beta posterior mean of hit rate for this category */
  H: z.number().min(0).max(1),
  /** resolved predictions in this category */
  n: z.number().int().min(0),
});
export type ConfidenceSignals = z.infer<typeof ConfidenceSignals>;
